"""This module provides functionality to determine the collected log
files from snapshot log collection and to provide all paths to the caller
"""
import os


class GnbSnapshotLogfileProvider:
    """Logfile provider for snapshot log files"""

    def get_snapshot_log_file(self, log_directory, collector_config):
        """Determines all snapshot log files and returns them in a list

        :param str log_directory: The Directory for the log files
        :param dict collector_config: The matching collector config for the snapshot
        """
        snapshot_files = []

        if collector_config['type'] == 'group':
            sub_dirs = [os.path.join(log_directory, x) for x in collector_config['members']]
            for sub_dir in sub_dirs:
                files = [os.path.join(sub_dir, filename) for filename in os.listdir(sub_dir)]
                snapshot_files += files
        elif collector_config['type'] == 'snapshot_sbts':
            zip_files = [os.path.join(log_directory, x) for x in os.listdir(log_directory)
                         if x.lower().endswith('.zip')]
            snapshot_files += zip_files

        return snapshot_files
